inline const Glyph* Find(uint32_t code) {
    size_t lo=0,hi=sizeof(glyphs)/sizeof(glyphs[0]);
    while(lo<hi) { size_t mid=lo+(hi-lo)/2; if(glyphs[mid].code<code)lo=mid+1;else hi=mid; }
    return lo<sizeof(glyphs)/sizeof(glyphs[0]) && glyphs[lo].code==code ? &glyphs[lo] : nullptr;
}
